118	export type SendMailOpts = {
119	  to: string;
120	  /** Optional Reply-To (e.g. route a contact-form reply straight to the sender). */
121	  replyTo?: string;
122	  /** Explicit subject. Optional when `template` is provided. */
123	  subject?: string;
124	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
125	  html?: string;
126	  text?: string;
127	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
128	  template?: string;
129	  /** Variables for `{{placeholders}}` when rendering from a template. */
130	  vars?: Record<string, unknown>;
131	  /** Attribution for the EmailLog row. */
132	  userId?: string | null;
133	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
134	  invoiceId?: string;
135	  /** Extra attachments. */
136	  attachments?: MailAttachment[];
137	  /**
138	   * What KIND of message this is, for the notification-preference policy in
139	   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
140	   * the customer's choice centrally — see the gate below.
141	   *
142	   * Omitting it means "always send", which is the safe default: a message must
143	   * never be dropped because someone forgot to classify it.
144	   */
145	  kind?: NotifyKind;
146	};
147	
148	/**
149	 * Send an email. Never throws — logs and returns false on failure so callers
150	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
151	 * FAILED + error otherwise) for the admin Logs viewer.
152	 *
153	 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
154	 * `User.notificationPrefs` was a column the customer edited and nothing read, so
155	 * turning off "email me about billing" changed nothing. Gating each send site
156	 * individually would have fixed today's sites and left every future one to
157	 * re-introduce the bug; gating centrally means a new send site inherits the
158	 * policy automatically and per-site checks become defence in depth.
159	 *
160	 * Two deliberate properties, both fail-open:
161	 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
162	 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
163	 *     the database, and also on a lookup error. A payment-failure or suspension
164	 *     warning must not be lost because a preference read failed.
165	 */
166	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
167	  // Preference gate. CRITICAL kinds (payment failed, suspension, security
168	  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
169	  // -circuit to true, so this costs nothing on the paths that matter most.
170	  if (opts.kind && opts.userId) {
171	    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
172	    if (!allowed) {
173	      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
174	      return false;
175	    }
176	  }
177	
178	  // Resolve subject/html: prefer explicit values, otherwise render the template.
179	  let subject = opts.subject ?? "";
180	  let html = opts.html ?? "";
181	  const templateKey = opts.template ?? null;
182	
183	  if (templateKey && !opts.html) {
184	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
185	    subject = opts.subject ?? rendered.subject;
186	    html = rendered.html;
187	  }
188	
189	  // Assemble attachments (invoice auto-attaches for the relevant templates).
190	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
191	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
192	  if (wantInvoice && opts.invoiceId) {
193	    const att = await invoiceAttachment(opts.invoiceId);
194	    if (att) attachments.push(att);
195	  }
196	
197	  try {
198	    const c = await loadSmtp();
199	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
200	      console.warn("[mailer] not configured — skipping email:", subject);
201	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
202	      return false;
203	    }
204	    const t = transport(c);
205	    await t.sendMail({
206	      from: c.from,
207	      to: opts.to,
208	      replyTo: opts.replyTo || undefined,
209	      subject,
210	      html,
211	      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
212	      attachments: attachments.length ? attachments : undefined,
213	    });
214	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
215	    return true;
216	  } catch (e) {
217	    console.error("[mailer] send failed:", e);
218	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
219	    return false;
220	  }
221	}
