101	/** Append a deliverability event (the analytics spine). Never throws to the caller. */
102	async function recordDeliverability(
103	  type: "SENT" | "FAILED" | "DELIVERED",
104	  ctx: { inboxId?: string | null; sendingDomainId?: string | null; campaignId: string; contactId?: string | null; sendId: string; meta?: string },
105	): Promise<void> {
106	  const t = type === "FAILED" ? "DEFERRED" : type; // FAILED maps to a soft/deferred signal
107	  try {
108	    await db.deliverabilityEvent.create({
109	      data: {
110	        type: t,
111	        inboxId: ctx.inboxId ?? null,
112	        sendingDomainId: ctx.sendingDomainId ?? null,
113	        campaignId: ctx.campaignId,
114	        contactId: ctx.contactId ?? null,
115	        sendId: ctx.sendId,
116	        meta: (ctx.meta ?? "").slice(0, 300),
117	      },
118	    });
119	  } catch {
120	    /* table not migrated / best-effort — analytics must never fail a send */
121	  }
122	}
