141	function startOfUtcDay(now = new Date()): Date {
142	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
143	}
144	
145	/** Current minute-of-day in a timezone (falls back to UTC on a bad tz). */
146	function minutesInTz(now: Date, tz: string): number {
147	  try {
148	    const parts = new Intl.DateTimeFormat("en-US", {
149	      timeZone: tz || "UTC",
150	      hour: "2-digit",
151	      minute: "2-digit",
152	      hour12: false,
153	    }).formatToParts(now);
154	    const h = Number(parts.find((p) => p.type === "hour")?.value ?? "0") % 24;
155	    const m = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
156	    return h * 60 + m;
157	  } catch {
158	    return now.getUTCHours() * 60 + now.getUTCMinutes();
159	  }
160	}
161	
162	function withinSendWindow(
163	  c: { sendWindowStart: number | null; sendWindowEnd: number | null; timezone: string },
164	  now: Date,
165	): boolean {
166	  if (c.sendWindowStart == null || c.sendWindowEnd == null) return true;
167	  const cur = minutesInTz(now, c.timezone || "UTC");
168	  const s = c.sendWindowStart;
169	  const e = c.sendWindowEnd;
170	  return s <= e ? cur >= s && cur < e : cur >= s || cur < e; // handle wrap past midnight
171	}
