173	type CampaignForSend = {
174	  id: string;
175	  brandId: string;
176	  listId: string;
177	  launchedAt: Date | null;
178	  sendWindowStart: number | null;
179	  sendWindowEnd: number | null;
180	  timezone: string;
181	};
