183	/**
184	 * Ensure a ColdSend row exists for every (contact, step) in a campaign, with the
185	 * scheduledFor honouring cumulative step delays from the launch anchor. Idempotent
186	 * — the unique(campaignId, contactId, stepId) + skipDuplicates makes re-runs free.
187	 */
188	async function scheduleCampaignSends(campaign: CampaignForSend): Promise<void> {
189	  const steps = await db.sequenceStep.findMany({
190	    where: { campaignId: campaign.id },
191	    orderBy: { stepOrder: "asc" },
192	    select: { id: true, delayDays: true },
193	  });
194	  if (steps.length === 0) return;
195	
196	  const base = campaign.launchedAt ?? new Date();
197	  // Cumulative offset (days) at each step.
198	  let cumulative = 0;
199	  const stepSchedule = steps.map((s) => {
200	    cumulative += Math.max(0, s.delayDays);
201	    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
202	  });
203	
204	  const members = await db.emailListMember.findMany({
205	    where: { listId: campaign.listId },
206	    select: { contactId: true },
207	  });
208	  if (members.length === 0) return;
209	
210	  const rows: { campaignId: string; contactId: string; stepId: string; scheduledFor: Date }[] = [];
211	  for (const m of members) {
212	    for (const s of stepSchedule) {
213	      rows.push({ campaignId: campaign.id, contactId: m.contactId, stepId: s.stepId, scheduledFor: s.scheduledFor });
214	    }
215	  }
216	  // createMany + skipDuplicates: never double-queues a message across sweeps.
217	  await db.coldSend.createMany({ data: rows, skipDuplicates: true });
218	}
