375	/**
376	 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
377	 * keeps everything below inert until a human enables sending on prod.
378	 */
379	export async function coldEmailSendSweep(): Promise<void> {
380	  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
381	  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;
382	
383	  let campaigns: CampaignForSend[];
384	  try {
385	    campaigns = await db.coldCampaign.findMany({
386	      where: { status: "SENDING" },
387	      select: {
388	        id: true,
389	        brandId: true,
390	        listId: true,
391	        launchedAt: true,
392	        sendWindowStart: true,
393	        sendWindowEnd: true,
394	        timezone: true,
395	      },
396	    });
397	  } catch {
398	    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
399	    return;
400	  }
401	  if (campaigns.length === 0) return;
402	
403	  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
404	  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
405	  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
406	  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
407	  const now = new Date();
408	
409	  let transport: MailTransport;
410	  try {
411	    transport = await getTransport("nxeon-smtp");
412	  } catch (err) {
413	    await logEvent("error", "coldemail.transport.init", { message: String(err) });
414	    return;
415	  }
416	
417	  let budget = MAX_SENDS_PER_SWEEP;
418	  for (const campaign of campaigns) {
419	    if (budget <= 0) break;
420	
421	    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
422	    if (!brand) continue;
423	
424	    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
425	    const eligibility = evaluateSendEligibility(brand, protectedSet);
426	    if (!eligibility.eligible) {
427	      await logEvent("warn", "coldemail.send.brand_blocked", {
428	        campaignId: campaign.id,
429	        brandId: brand.id,
430	        reasons: eligibility.reasons,
431	      });
432	      continue;
433	    }
434	
435	    const identity: SendIdentity = {
436	      id: brand.id,
437	      name: brand.name,
438	      fromName: brand.fromName,
439	      fromEmail: brand.fromEmail,
440	      replyTo: brand.replyTo,
441	      sendingDomain: brand.sendingDomain,
442	      physicalPostalAddress: brand.physicalPostalAddress,
443	    };
444	
445	    try {
446	      await scheduleCampaignSends(campaign);
447	      const sent = await processDueSends(campaign, identity, {
448	        now,
449	        transport,
450	        ceiling,
451	        warmupEnabled,
452	        footerDisclosure,
453	        budget,
454	      });
455	      budget -= sent;
456	      await maybeCompleteCampaign(campaign.id);
457	    } catch (err) {
458	      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
459	    }
460	  }
461	}
