1	// Cold Email Engine — bounce / complaint handling + complaint circuit breaker.
2	//
3	// This is the "use side" of deliverability protection: a bounce or spam complaint
4	// must (a) suppress the address so we never mail it again, and (b) feed the
5	// complaint-rate circuit breaker that pauses a whole brand before its reputation —
6	// and every other brand sharing the platform — is damaged.
7	//
8	// No live IMAP/FBL polling this phase. The seam is here: a server action or the
9	// inbound webhook stub (app/api/coldemail/feedback) calls `recordFeedback`, which
10	// is the single choke point. Wire SES SNS / Mailcow FBL into that route later.
11	
12	import { db } from "@/lib/db";
13	import { normalizeEmail, normalizeDomain } from "@/lib/coldemail/compliance";
14	import { getSetting } from "@/lib/settings";
15	import { logEvent } from "@/lib/log";
16	
17	export type FeedbackKind = "BOUNCE" | "COMPLAINT";
18	
19	/**
20	 * Look back this far when computing a brand's complaint rate. A rolling window
21	 * keeps one bad historical week from pinning the brand paused forever once hygiene
22	 * recovers.
23	 */
24	const COMPLAINT_WINDOW_DAYS = 30;
25	
26	/** Don't trip the breaker until there's enough volume for a rate to be meaningful. */
27	const COMPLAINT_MIN_SENDS = 50;
28	
29	/**
30	 * Record a bounce or complaint for an address: write a GLOBAL Suppression (so no
31	 * brand ever re-contacts it), attach the matching EmailEvent to the most recent
32	 * send if we can find one, and — for complaints — run the circuit breaker.
33	 *
34	 * Idempotent on the suppression (check-then-insert on the GLOBAL row). Never
35	 * throws to the caller — feedback ingestion must not fail a webhook.
36	 */
37	export async function recordFeedback(
38	  rawEmail: string,
39	  kind: FeedbackKind,
40	  opts: { brandId?: string | null; note?: string } = {},
41	): Promise<{ ok: boolean; suppressed: boolean; brandPaused?: boolean }> {
42	  const email = normalizeEmail(rawEmail);
43	  if (!email || !email.includes("@")) return { ok: false, suppressed: false };
44	
45	  try {
46	    // 1) GLOBAL suppression (idempotent). Bounces + complaints are always global —
47	    //    a bad address stays bad for every brand.
48	    const existing = await db.suppression.findFirst({ where: { email, scope: "GLOBAL" }, select: { id: true } });
49	    if (!existing) {
50	      await db.suppression.create({ data: { email, scope: "GLOBAL", reason: kind } });
51	    }
52	
53	    // 2) Attach an event to the latest send to this address, if one exists, so the
54	    //    campaign stats reflect the bounce/complaint.
55	    const contact = await db.contact.findUnique({ where: { email }, select: { id: true } });
56	    let brandId = opts.brandId ?? null;
57	    if (contact) {
58	      const lastSend = await db.coldSend.findFirst({
59	        where: { contactId: contact.id },
60	        orderBy: { createdAt: "desc" },
61	        select: { id: true, campaign: { select: { brandId: true } } },
62	      });
63	      if (lastSend) {
64	        await db.emailEvent.create({
