85	export async function complaintStats(brandId: string): Promise<{ sends: number; complaints: number; rate: number }> {
86	  const since = new Date(Date.now() - COMPLAINT_WINDOW_DAYS * 86_400_000);
87	  const sends = await db.coldSend.count({
88	    where: { campaign: { brandId }, sentAt: { gte: since } },
89	  });
90	  const complaints = await db.emailEvent.count({
91	    where: { type: "COMPLAINT", createdAt: { gte: since }, send: { campaign: { brandId } } },
92	  });
93	  const rate = sends > 0 ? complaints / sends : 0;
94	  return { sends, complaints, rate };
95	}
