97	/**
98	 * Pause the brand if its complaint rate is over the configured threshold and it
99	 * has enough volume to matter. Returns whether it ended up paused. This is what
100	 * stops one bad campaign from taking down all three brands' shared reputation.
101	 */
102	export async function maybeTripCircuitBreaker(brandId: string): Promise<boolean> {
103	  const threshold = Number(await getSetting("coldemail_complaint_threshold")) || 0.003;
104	  const { sends, complaints, rate } = await complaintStats(brandId);
105	  if (sends < COMPLAINT_MIN_SENDS) return false;
106	  if (rate < threshold) return false;
107	
108	  const brand = await db.brand.findUnique({ where: { id: brandId }, select: { sendingPaused: true } });
109	  if (brand?.sendingPaused) return true; // already paused
110	
111	  await db.brand.update({
112	    where: { id: brandId },
113	    data: {
114	      sendingPaused: true,
115	      pausedReason: `Complaint rate ${(rate * 100).toFixed(2)}% (${complaints}/${sends}) exceeded ${(threshold * 100).toFixed(2)}% — auto-paused`,
116	    },
117	  });
118	  await logEvent("warn", "coldemail.circuit_breaker.trip", { brandId, rate, complaints, sends, threshold });
119	  return true;
120	}
