633	/** Minutes-from-midnight for an "HH:MM" string, or null if blank/invalid. */
634	function parseHhmm(v: string): number | null {
635	  const m = /^(\d{1,2}):(\d{2})$/.exec(v.trim());
636	  if (!m) return null;
637	  const h = Number(m[1]);
638	  const min = Number(m[2]);
639	  if (h > 23 || min > 59) return null;
640	  return h * 60 + min;
641	}
