650	  const timezone = String(formData.get("timezone") ?? "UTC").trim().slice(0, 64) || "UTC";
651	
652	  const sendWindowStart = startRaw ? parseHhmm(startRaw) : null;
653	  const sendWindowEnd = endRaw ? parseHhmm(endRaw) : null;
654	  if ((startRaw && sendWindowStart === null) || (endRaw && sendWindowEnd === null)) {
655	    return { error: "Send window times must be HH:MM (24-hour)." };
