// ===========================================================================
// Cold Email Engine — OVERHAUL PHASE 1: the Reply Loop + Master Inbox.
//
// ADDITIVE. Turns the send-only engine into a two-way platform: an IMAP poller
// (worker/coldemail-inbox.ts) captures replies into Conversation/Message, halts
// the contact's remaining sequence sends, and classifies the reply. All inert
// until an Inbox has real IMAP/SMTP credentials — no creds, nothing connects.
// ===========================================================================

/// A reply thread with one contact, seen from one of our inboxes. The unibox's
/// unit. Status starts OPEN and is set by the classifier (or an operator): the
/// interested/not-interested/OOO/auto-reply/unsubscribe buckets a 2026 unibox needs.
enum ConversationStatus {
  OPEN
  REPLIED
  INTERESTED
  NOT_INTERESTED
  AUTO_REPLY
  OUT_OF_OFFICE
  UNSUBSCRIBE
  CLOSED
}

/// Which way a message travelled: OUTBOUND = we sent it (a cold send or an
/// operator reply), INBOUND = the contact replied to us (captured over IMAP).
enum MessageDirection {
  OUTBOUND
  INBOUND
}

/// A conversation thread. Keyed unique on (inboxId, contactId) so the poller can
/// upsert idempotently — one thread per contact per mailbox, whatever campaign
/// touched them. `unread` drives the unibox badge; `category` stores the raw
/// classifier label for audit even when it doesn't map cleanly to `status`.
model Conversation {
  id            String             @id @default(cuid())
  contactId     String
  campaignId    String?
  inboxId       String
  subject       String             @default("")
  status        ConversationStatus @default(OPEN)
  category      String             @default("") // raw classifier bucket / operator note
  lastMessageAt DateTime           @default(now())
  unread        Boolean            @default(true)
  createdAt     DateTime           @default(now())

  contact  Contact       @relation(fields: [contactId], references: [id], onDelete: Cascade)
  campaign ColdCampaign? @relation(fields: [campaignId], references: [id], onDelete: SetNull)
  inbox    Inbox         @relation(fields: [inboxId], references: [id], onDelete: Cascade)
  messages Message[]

  @@unique([inboxId, contactId])
  @@index([status])
  @@index([campaignId])
  @@index([inboxId])
  @@index([unread])
  @@index([lastMessageAt])
}

/// One message in a Conversation — inbound (parsed from IMAP) or outbound (a cold
/// send or an operator reply). `messageId`/`inReplyTo`/`references` are the RFC
/// threading headers used to stitch replies back to the originating ColdSend and
/// to build correctly-threaded outbound replies. `coldSendId` links an inbound
/// reply to the send it answered when threading resolves it.
model Message {
  id             String           @id @default(cuid())
  conversationId String
  direction      MessageDirection
  fromAddr       String           @default("")
  toAddr         String           @default("")
  subject        String           @default("")
  bodyText       String           @default("")
  bodyHtml       String           @default("")
  messageId      String           @default("") // RFC 5322 Message-ID (angle brackets kept)
  inReplyTo      String           @default("")
  references     String           @default("") // space-separated Message-IDs
  coldSendId     String?
  sentAt         DateTime?
  receivedAt     DateTime?
  createdAt      DateTime         @default(now())

  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  coldSend     ColdSend?    @relation(fields: [coldSendId], references: [id], onDelete: SetNull)

  @@index([conversationId])
  @@index([direction])
  @@index([messageId])
  @@index([coldSendId])
  @@index([createdAt])
}

/// An outbound webhook subscription. Fires HMAC-signed POSTs on reply / interested
/// / unsubscribe events so Nxeon or an external CRM can react. `secretEnc` is the
/// signing secret, stored ENCRYPTED via lib/crypto-box. `events` is the set of
/// event keys this endpoint wants (reply | interested | unsubscribe).
model WebhookEndpoint {
  id          String   @id @default(cuid())
  url         String
  secretEnc   String   @default("") // encryptSecret(...) — HMAC signing secret, never plaintext
  events      String[] @default([])
  active      Boolean  @default(true)
  lastFiredAt DateTime?
  lastStatus  String   @default("") // last delivery result ("204", "timeout", "error: …")
  createdAt   DateTime @default(now())

  @@index([active])
}

// ===========================================================================
// Sitewave — productized web-design agency (add-on module). PHASE 1.

input.content:
// Cold Email Engine — RFC 5322 email threading helpers (Overhaul Phase 1).
//
// PURE + dependency-free. Both the IMAP poller (matching an inbound reply back to
// the send it answered) and the reply sender (building correctly-threaded outbound
// headers) rely on these, and the test suite exercises them without any I/O.
//
// A well-behaved reply carries `In-Reply-To: <the-message-id-it-answers>` and a
// `References:` chain of every Message-ID in the thread. To keep a thread intact
// when WE reply we must set `In-Reply-To` to the last message we're answering and
// append it to the running `References` chain (RFC 5322 §3.6.4).

/** Extract every `<message-id>` token from an In-Reply-To / References header. */
export function extractMessageIds(header: string | null | undefined): string[] {
  if (!header) return [];
  const out: string[] = [];
  const re = /<([^<>\s]+)>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(header)) !== null) {
    out.push(`<${m[1]}>`);
  }
  // Fallback: a bare id with no angle brackets (some servers omit them).
  if (out.length === 0) {
    const bare = header.trim();
    if (bare && !/\s/.test(bare)) out.push(bare.startsWith("<") ? bare : `<${bare}>`);
  }
  return out;
}

/** Normalize a raw Message-ID to `<id>` form (idempotent; blank stays blank). */
export function normalizeMessageId(id: string | null | undefined): string {
  const v = (id ?? "").trim();
  if (!v) return "";
  if (v.startsWith("<") && v.endsWith(">")) return v;
  return `<${v.replace(/^<|>$/g, "")}>`;
}

/** Build a reply subject: prefix `Re: ` once, never stacking `Re: Re:`. */
export function replySubject(subject: string | null | undefined): string {
  const s = (subject ?? "").trim();
  if (!s) return "Re:";
  return /^re:/i.test(s) ? s : `Re: ${s}`;
}

export type ThreadHeaders = {
  "In-Reply-To"?: string;
  References?: string;
};

/**
 * Build the threading headers for an outbound reply.
 *
 * @param parentMessageId  the Message-ID of the message we are replying to.
 * @param parentReferences the References header of the message we are replying to.
 *
 * References becomes the parent's chain + the parent's own Message-ID, de-duped
 * and order-preserving. In-Reply-To is the parent's Message-ID.
 */
export function buildThreadHeaders(
  parentMessageId: string | null | undefined,
  parentReferences?: string | null | undefined,
): ThreadHeaders {
  const parent = normalizeMessageId(parentMessageId);
  if (!parent) return {};

  const chain = extractMessageIds(parentReferences);
  const refs: string[] = [];
  const seen = new Set<string>();
  for (const id of [...chain, parent]) {
    if (id && !seen.has(id)) {
      seen.add(id);
      refs.push(id);
    }
  }
  return {
    "In-Reply-To": parent,
    References: refs.join(" "),
  };
}

// Cold Email Engine — match an inbound reply to the ColdSend it answered (Phase 1).
//
// PURE + dependency-free so the poller and the tests share one code path.
//
// Precedence (RFC threading first, recipient fallback last):
//   1. In-Reply-To — the single strongest signal (the exact message being answered).
//   2. References — any Message-ID in the thread chain that maps to one of our sends.
//   3. Recipient fallback — the sender's address maps to a contact whose most-recent
//      send from this inbox we already know. Resolved by the caller (needs the DB),
//      so this module only does the header-based match.

import { extractMessageIds, normalizeMessageId } from "./threading";

/**
 * Resolve which of our sends an inbound reply answered, using only its threading
 * headers and a map of our sent Message-IDs → ColdSend id.
 *
 * @param inReplyTo   the reply's In-Reply-To header (may be blank).
 * @param references  the reply's References header (may be blank).
 * @param sentIndex   Map of every ColdSend.messageId (normalized `<id>`) → ColdSend id.
 * @returns the matched ColdSend id, or null when no header points at a known send.
 */
export function matchColdSendId(
  inReplyTo: string | null | undefined,
  references: string | null | undefined,
  sentIndex: Map<string, string>,
): string | null {
  // 1) In-Reply-To wins outright.
  for (const id of extractMessageIds(inReplyTo)) {
    const hit = sentIndex.get(id);
    if (hit) return hit;
  }
  // 2) Walk the References chain newest-last; the most recent match is the best.
  const refs = extractMessageIds(references);
  for (let i = refs.length - 1; i >= 0; i--) {
    const hit = sentIndex.get(refs[i]);
    if (hit) return hit;
  }
  return null;
}

/**
 * Build the lookup index the matcher needs from raw ColdSend rows. Skips rows with
 * no stored Message-ID (nothing to thread against). Normalizes ids to `<id>` form.
 */
export function buildSentIndex(sends: Array<{ id: string; messageId: string | null }>): Map<string, string> {
  const idx = new Map<string, string>();
  for (const s of sends) {
    const mid = normalizeMessageId(s.messageId);
    if (mid) idx.set(mid, s.id);
  }
  return idx;
}

// Cold Email Engine — reply classification (Overhaul Phase 1).
//
// Two layers, both here:
//   1. PURE rule-based detection (no I/O) — catches unsubscribe / opt-out phrasing,
//      out-of-office, and automated bounces/auto-replies. Runs ALWAYS, so an
//      unsubscribe is honoured even with no Anthropic key configured. The tests
//      exercise this + the class→status/stage mapping directly.
//   2. An OPTIONAL AI refinement (askClaude) into interested / not-interested. It
//      only ever UPGRADES a reply the rules left ambiguous; it can never override a
//      rule-detected unsubscribe. Degrades gracefully to null with no API key.
//
// The five buckets mirror the ConversationStatus reply values.

import { askClaude, effectiveKeyFor, type ClaudeMessage } from "@/lib/anthropic";

export type ReplyClass = "INTERESTED" | "NOT_INTERESTED" | "AUTO_REPLY" | "OUT_OF_OFFICE" | "UNSUBSCRIBE";

// Prisma enum string unions (kept as literals so this module stays free of the
// generated client — it must be importable in a DB-less test).
export type ConversationStatusValue =
  | "OPEN"
  | "REPLIED"
  | "INTERESTED"
  | "NOT_INTERESTED"
  | "AUTO_REPLY"
  | "OUT_OF_OFFICE"
  | "UNSUBSCRIBE"
  | "CLOSED";

export type ContactStageValue =
  | "NEW"
  | "CONTACTED"
  | "REPLIED"
  | "INTERESTED"
  | "MEETING_BOOKED"
  | "WON"
  | "LOST";

// ---------------------------------------------------------------------------
// PURE rule-based detection
// ---------------------------------------------------------------------------

const UNSUB_PATTERNS: RegExp[] = [
  /\bunsubscribe\b/i,
  /\bopt[\s-]?out\b/i,
  /\bremove me\b/i,
  /\btake me off\b/i,
  /\bstop (?:emailing|contacting|messaging) me\b/i,
  /\bdo not (?:contact|email|reach out)\b/i,
  /\bdon'?t (?:contact|email) me\b/i,
  /\bno longer (?:wish|want) to (?:receive|hear)\b/i,
];

const OOO_PATTERNS: RegExp[] = [
  /\bout of (?:the )?office\b/i,
  /\bon (?:vacation|holiday|annual leave|parental leave|maternity leave)\b/i,
  /\baway from my (?:desk|email)\b/i,
  /\bwill be (?:back|returning) on\b/i,
  /\blimited access to (?:my )?email\b/i,
];

const AUTO_PATTERNS: RegExp[] = [
  /\bauto(?:matic|mated)?[\s-]?reply\b/i,
  /\bthis is an automated\b/i,
  /\bdo[\s-]?not[\s-]?reply\b/i,
  /\bno[\s-]?reply@\b/i,
  /\bdelivery (?:status notification|has failed)\b/i,
  /\bundeliverable\b/i,
  /\bmailer-daemon\b/i,
  /\baddress not found\b/i,
];

const NOT_INTERESTED_PATTERNS: RegExp[] = [
  /\bnot interested\b/i,
  /\bno thanks?\b/i,
  /\bnot (?:a )?(?:good )?(?:fit|match)\b/i,
  /\bwe(?:'re| are) (?:all )?(?:set|good)\b/i,
  /\balready (?:have|using|work with)\b/i,
  /\bplease stop\b/i,
];

const INTERESTED_PATTERNS: RegExp[] = [
  /\b(?:interested|keen|curious)\b/i,
  /\btell me more\b/i,
  /\b(?:sounds|looks) (?:good|great|interesting)\b/i,
  /\b(?:book|schedule|set up|arrange) (?:a )?(?:call|meeting|demo|time)\b/i,
  /\bhappy to (?:chat|talk|connect)\b/i,
  /\bwhat(?:'s| is) (?:the |your )?(?:pricing|price|cost)\b/i,
  /\bhow (?:much|does it work)\b/i,
];

function anyMatch(text: string, patterns: RegExp[]): boolean {
  return patterns.some((re) => re.test(text));
}

/** Is this reply an unsubscribe / opt-out request? Rule-only, never AI-gated. */
export function isUnsubscribeRequest(text: string): boolean {
  return anyMatch(text ?? "", UNSUB_PATTERNS);
}

/**
 * Rule-based first pass over the reply text (subject + body). Returns a definite
 * class when the rules are confident, else null (hand off to the AI layer). Order
 * matters: an unsubscribe phrase wins over everything, then automated messages,
 * then out-of-office, then the softer interested/not-interested cues.
 */
export function ruleClassify(text: string): ReplyClass | null {
  const t = (text ?? "").toLowerCase();
  if (!t.trim()) return null;
  if (anyMatch(t, UNSUB_PATTERNS)) return "UNSUBSCRIBE";
  if (anyMatch(t, AUTO_PATTERNS)) return "AUTO_REPLY";
  if (anyMatch(t, OOO_PATTERNS)) return "OUT_OF_OFFICE";
  if (anyMatch(t, NOT_INTERESTED_PATTERNS)) return "NOT_INTERESTED";
  if (anyMatch(t, INTERESTED_PATTERNS)) return "INTERESTED";
  return null;
}

// ---------------------------------------------------------------------------
// Class → ConversationStatus / ContactStage mapping (PURE)
// ---------------------------------------------------------------------------

/** Map a reply class to the conversation status it sets. */
export function classToConversationStatus(c: ReplyClass): ConversationStatusValue {
  switch (c) {
    case "INTERESTED":
      return "INTERESTED";
    case "NOT_INTERESTED":
      return "NOT_INTERESTED";
    case "AUTO_REPLY":
      return "AUTO_REPLY";
    case "OUT_OF_OFFICE":
      return "OUT_OF_OFFICE";
    case "UNSUBSCRIBE":
      return "UNSUBSCRIBE";
  }
}

/**
 * Map a reply class to the contact stage it advances to, or null to leave the
 * stage at REPLIED (auto-replies / OOO are not a human signal either way). A reply
 * has already moved the contact to REPLIED before this is applied.
 */
export function classToContactStage(c: ReplyClass): ContactStageValue | null {
  switch (c) {
    case "INTERESTED":
      return "INTERESTED";
    case "NOT_INTERESTED":
      return "LOST";
    case "UNSUBSCRIBE":
      return "LOST";
    case "AUTO_REPLY":
    case "OUT_OF_OFFICE":
      return null;
  }
}

/** Does this class require a GLOBAL suppression? (Unsubscribe only.) */
export function classNeedsSuppression(c: ReplyClass): boolean {
  return c === "UNSUBSCRIBE";
}

/** Parse a raw AI answer down to one of the five buckets, or null if unparseable. */
export function parseAiClass(raw: string): ReplyClass | null {
  const u = (raw ?? "").toUpperCase();
  const buckets: ReplyClass[] = ["UNSUBSCRIBE", "OUT_OF_OFFICE", "AUTO_REPLY", "NOT_INTERESTED", "INTERESTED"];
  for (const b of buckets) {
    if (u.includes(b) || u.includes(b.replace(/_/g, " "))) return b;
  }
  return null;
}

const CLASSIFY_SYSTEM = `You classify a single inbound reply to a B2B cold outreach email into EXACTLY ONE bucket. Answer with ONLY the bucket word, nothing else.

Buckets:
- INTERESTED — wants to learn more, book a call/demo, asks about pricing, positive engagement.
- NOT_INTERESTED — declines, not a fit, already sorted, asks to be left alone (but NOT a formal unsubscribe).
- OUT_OF_OFFICE — an automatic away/vacation message.
- AUTO_REPLY — any other automated message (ticket auto-ack, mailer-daemon, no-reply notice).
- UNSUBSCRIBE — explicitly asks to unsubscribe / opt out / be removed / stop all contact.

Reply with one of: INTERESTED, NOT_INTERESTED, OUT_OF_OFFICE, AUTO_REPLY, UNSUBSCRIBE.`;

/**
 * Full classification for a captured reply.
 *
 *  - Rule pass runs first and is authoritative for UNSUBSCRIBE / OOO / AUTO_REPLY.
 *  - If the rules are ambiguous AND an Anthropic key is available, ask Claude to
 *    pick a bucket (used mainly to separate INTERESTED vs NOT_INTERESTED).
 *  - With no key and ambiguous rules, returns null → the caller leaves the
 *    conversation OPEN (honest: we didn't classify it).
 *
 * Never throws — a classification failure must not break reply ingestion.
 */
export async function classifyReply(
  subject: string,
  body: string,
  opts: { anthropicKeyEnc?: string | null } = {},
): Promise<ReplyClass | null> {
  const text = `${subject ?? ""}\n\n${body ?? ""}`.trim();
  const rule = ruleClassify(text);
  // Rules are decisive for the "safety" buckets — never let AI override them.
  if (rule === "UNSUBSCRIBE" || rule === "AUTO_REPLY" || rule === "OUT_OF_OFFICE") return rule;

  const key = effectiveKeyFor(opts);
  if (!key) return rule; // no AI available — trust the (possibly null) rule verdict

  try {
    const messages: ClaudeMessage[] = [
      { role: "user", content: `Subject: ${subject ?? ""}\n\nBody:\n${(body ?? "").slice(0, 4000)}` },
    ];
    const answer = await askClaude(key, messages, CLASSIFY_SYSTEM, { maxTokens: 16, timeoutMs: 20_000 });
    return parseAiClass(answer) ?? rule;
  } catch {
    return rule;
  }
}

// Cold Email Engine — outbound webhook dispatcher (Overhaul Phase 1).
//
// Fires HMAC-signed POSTs to subscribed endpoints on reply / interested /
// unsubscribe events so Nxeon or an external CRM can react. Best-effort: a slow or
// failing endpoint never blocks or breaks reply ingestion. Signing secrets are
// stored ENCRYPTED (WebhookEndpoint.secretEnc) and decrypted only here at send.
//
// `signPayload` is PURE (crypto only) so it is unit-testable and matches what a
// receiver recomputes to verify authenticity.

import { createHmac } from "node:crypto";
import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { logEvent } from "@/lib/log";

export type WebhookEvent = "reply" | "interested" | "unsubscribe";

/** The set of events an endpoint may subscribe to. Validated in the admin action. */
export const WEBHOOK_EVENTS: WebhookEvent[] = ["reply", "interested", "unsubscribe"];

/**
 * HMAC-SHA256 hex signature of the exact JSON body, keyed by the endpoint's
 * secret. Sent as `X-Nxeon-Signature: sha256=<hex>`; a receiver recomputes it over
 * the raw body to authenticate the call. PURE.
 */
export function signPayload(secret: string, body: string): string {
  return `sha256=${createHmac("sha256", secret || "").update(body, "utf8").digest("hex")}`;
}

export type WebhookPayload = {
  event: WebhookEvent;
  conversationId: string;
  contactEmail: string;
  contactName?: string;
  campaignId?: string | null;
  inboxEmail?: string;
  status?: string;
  snippet?: string;
  occurredAt: string;
};

async function postOne(
  endpoint: { id: string; url: string; secretEnc: string },
  payload: WebhookPayload,
): Promise<void> {
  const body = JSON.stringify(payload);
  const secret = decryptSecret(endpoint.secretEnc) ?? "";
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 10_000);
  let status = "error";
  try {
    const res = await fetch(endpoint.url, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "user-agent": "Nxeon-ColdEmail-Webhook/1",
        "x-nxeon-event": payload.event,
        "x-nxeon-signature": signPayload(secret, body),
      },
      body,
      signal: controller.signal,
    });
    status = String(res.status);
  } catch (err) {
    status = `error: ${String((err as Error)?.message ?? err).slice(0, 120)}`;
  } finally {
    clearTimeout(timer);
  }
  await db.webhookEndpoint
    .update({ where: { id: endpoint.id }, data: { lastFiredAt: new Date(), lastStatus: status.slice(0, 200) } })
    .catch(() => null);
}

/**
 * Fire an event to every active endpoint subscribed to it. Never throws. Endpoints
 * are POSTed in parallel; failures are recorded on the row, not propagated.
 */
export async function fireWebhooks(event: WebhookEvent, payload: Omit<WebhookPayload, "event">): Promise<void> {
  let endpoints: Array<{ id: string; url: string; secretEnc: string }>;
  try {
    endpoints = await db.webhookEndpoint.findMany({
      where: { active: true, events: { has: event } },
      select: { id: true, url: true, secretEnc: true },
    });
  } catch {
    return; // table not migrated on this env — no-op
  }
  if (endpoints.length === 0) return;
  const full: WebhookPayload = { ...payload, event };
  await Promise.allSettled(endpoints.map((e) => postOne(e, full))).catch(() => null);
  await logEvent("info", "coldemail.webhook.fire", { event, count: endpoints.length }).catch(() => null);
}

/** Fire a synthetic test event at ONE endpoint (admin "test-fire" button). */
export async function testFireEndpoint(id: string): Promise<{ ok: boolean; status: string }> {
  const ep = await db.webhookEndpoint.findUnique({ where: { id }, select: { id: true, url: true, secretEnc: true } });
  if (!ep) return { ok: false, status: "not found" };
  await postOne(ep, {
    event: "reply",
    conversationId: "test",
    contactEmail: "test@example.com",
    contactName: "Test Contact",
    inboxEmail: "you@mail.example.com",
    status: "OPEN",
    snippet: "This is a test webhook fired from the Nxeon Cold Email admin.",
    occurredAt: new Date().toISOString(),
  });
  const after = await db.webhookEndpoint.findUnique({ where: { id }, select: { lastStatus: true } });
  const status = after?.lastStatus ?? "unknown";
  return { ok: /^2\d\d$/.test(status), status };
}

// Cold Email Engine — threaded reply send from an inbox's own SMTP (Phase 1).
//
// This is the "1:1 operator reply" path. It is NORMAL email to an existing
// conversation (someone who already replied to us), so it is allowed even while
// the bulk kill-switch `cold_email_sending_enabled` is OFF — it never touches the
// bulk queue. It sends from the conversation's inbox using THAT inbox's own SMTP
// credentials (decrypted from smtpPassEnc), sets the RFC threading headers so the
// message stays in the thread, logs an OUTBOUND Message, and marks the
// conversation read.
//
// INERT without creds: an inbox with a blank smtpHost cannot send — the caller
// gets a clear error instead of a connection attempt.

import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { NxeonSmtpTransport, markdownToHtml, type RenderedMessage } from "@/lib/coldemail/sender";
import { wrapEmail } from "@/lib/email-render";
import { buildThreadHeaders, replySubject, normalizeMessageId } from "@/lib/coldemail/threading";
import { logEvent } from "@/lib/log";

/** Mint a fresh Message-ID for an outbound reply so later replies thread to it. */
function newMessageId(fromAddr: string): string {
  const domain = (fromAddr.split("@")[1] || "nxeon.cloud").trim() || "nxeon.cloud";
  const rand = `${Date.now().toString(36)}.${Math.random().toString(36).slice(2, 12)}`;
  return `<${rand}@${domain}>`;
}

export type SendReplyResult = { ok: true; messageId: string } | { ok: false; error: string };

/**
 * Send a threaded reply within a conversation from its inbox's SMTP, and log the
 * outbound Message. Threads onto the most recent message in the conversation.
 */
export async function sendConversationReply(opts: {
  conversationId: string;
  bodyMarkdown: string;
  subjectOverride?: string;
}): Promise<SendReplyResult> {
  const body = (opts.bodyMarkdown ?? "").trim();
  if (!body) return { ok: false, error: "Write a message before sending." };

  const conversation = await db.conversation.findUnique({
    where: { id: opts.conversationId },
    include: {
      contact: { select: { email: true } },
      inbox: {
        select: {
          email: true,
          smtpHost: true,
          smtpPort: true,
          smtpUser: true,
          smtpPassEnc: true,
          smtpTls: true,
        },
      },
      // Newest message = the one we thread our reply onto.
      messages: { orderBy: { createdAt: "desc" }, take: 1 },
    },
  });
  if (!conversation) return { ok: false, error: "Conversation not found." };

  const inbox = conversation.inbox;
  if (!inbox.smtpHost || !inbox.smtpUser) {
    return { ok: false, error: "This inbox has no SMTP credentials configured — set them on Domains & inboxes first." };
  }
  const pass = decryptSecret(inbox.smtpPassEnc) ?? "";

  const to = conversation.contact.email;
  const parent = conversation.messages[0] ?? null;
  const subject = (opts.subjectOverride ?? "").trim() || replySubject(conversation.subject);
  const thread = parent ? buildThreadHeaders(parent.messageId, parent.references) : {};
  const messageId = newMessageId(inbox.email);

  const bodyHtml = wrapEmail(markdownToHtml(body), { preheader: subject });
  const headers: Record<string, string> = {
    "Message-ID": messageId,
    "X-Nxeon-Cold-Email": "reply",
    ...thread,
  };

  const msg: RenderedMessage = {
    from: inbox.email,
    to,
    subject,
    html: bodyHtml,
    text: body,
    headers,
  };

  try {
    const transport = new NxeonSmtpTransport({
      host: inbox.smtpHost,
      port: inbox.smtpPort,
      user: inbox.smtpUser,
      pass,
      secure: inbox.smtpTls,
    });
    await transport.send(msg);
  } catch (err) {
    const error = String((err as Error)?.message ?? err).slice(0, 300);
    await logEvent("error", "coldemail.reply.send", { conversationId: opts.conversationId, error });
    return { ok: false, error: `Send failed: ${error}` };
  }

  const now = new Date();
  await db.message.create({
    data: {
      conversationId: conversation.id,
      direction: "OUTBOUND",
      fromAddr: inbox.email,
      toAddr: to,
      subject,
      bodyText: body,
      bodyHtml,
      messageId,
      inReplyTo: thread["In-Reply-To"] ?? "",
      references: thread.References ?? "",
      sentAt: now,
    },
  });

  await db.conversation.update({
    where: { id: conversation.id },
    // An operator reply clears the unread flag and, if the thread was still just
    // OPEN, moves it to REPLIED. A classified status (INTERESTED, etc.) is preserved.
    data: {
      unread: false,
      lastMessageAt: now,
      status: conversation.status === "OPEN" ? "REPLIED" : conversation.status,
    },
  });

  await logEvent("info", "coldemail.reply.sent", { conversationId: conversation.id, messageId: normalizeMessageId(messageId) });
  return { ok: true, messageId };
}

// Cold Email Engine — IMAP reply poller (Overhaul Phase 1).
//
// Registered on the worker loop (worker/index.ts). For each Inbox that has REAL
// IMAP credentials it connects, fetches messages newer than the stored UID
// bookmark, and for every reply from a known contact it:
//   1. upserts a Conversation + appends an INBOUND Message (idempotent on UID),
//   2. moves the contact to stage REPLIED,
//   3. HALTS the contact's remaining queued sends (mail-side reply detection),
//   4. writes a REPLY EmailEvent + DeliverabilityEvent for the analytics spine,
//   5. classifies the reply (rules first, then Claude if a key exists) and sets the
//      conversation status + contact stage; an UNSUBSCRIBE writes a GLOBAL Suppression,
//   6. fires reply / interested / unsubscribe webhooks.
//
// SAFETY: this is send-INDEPENDENT and creds-gated. An inbox with a blank imapHost
// is never touched — no creds, no connection. It reads mail; it never sends here.
// Degrades gracefully with no ANTHROPIC_API_KEY (the reply stays classified only by
// rules, else left OPEN). Never throws to the caller — a bad mailbox is logged and
// skipped so one inbox can't stall the sweep.

import { ImapFlow } from "imapflow";
import { simpleParser, type ParsedMail } from "mailparser";
import { db } from "../lib/db";
import { decryptSecret } from "../lib/crypto-box";
import { normalizeEmail } from "../lib/coldemail/compliance";
import { matchColdSendId, buildSentIndex } from "../lib/coldemail/inbox-match";
import { normalizeMessageId } from "../lib/coldemail/threading";
import {
  classifyReply,
  isUnsubscribeRequest,
  classToConversationStatus,
  classToContactStage,
  classNeedsSuppression,
  type ReplyClass,
} from "../lib/coldemail/classify";
import { fireWebhooks } from "../lib/coldemail/webhooks";
import { logEvent } from "../lib/log";

type PollInbox = {
  id: string;
  email: string;
  imapHost: string;
  imapPort: number;
  imapUser: string;
  imapPassEnc: string;
  imapTls: boolean;
  lastImapUid: number;
};

/** Cap on messages examined per inbox per sweep — keeps a first poll bounded. */
const MAX_MESSAGES_PER_INBOX = 200;

/** The sweep entrypoint. Polls every credentialed inbox; isolates failures. */
export async function coldEmailInboxPoll(): Promise<void> {
  let inboxes: PollInbox[];
  try {
    inboxes = await db.inbox.findMany({
      where: { imapHost: { not: "" }, imapUser: { not: "" } },
      select: {
        id: true,
        email: true,
        imapHost: true,
        imapPort: true,
        imapUser: true,
        imapPassEnc: true,
        imapTls: true,
        lastImapUid: true,
      },
    });
  } catch {
    return; // tables not migrated on this env — behave like a no-op
  }
  if (inboxes.length === 0) return; // no credentialed inboxes — nothing connects

  for (const ib of inboxes) {
    try {
      await pollOneInbox(ib);
    } catch (err) {
      await logEvent("error", "coldemail.inbox.poll", { inboxId: ib.id, message: String((err as Error)?.message ?? err) });
    }
  }
}

async function pollOneInbox(ib: PollInbox): Promise<void> {
  const pass = decryptSecret(ib.imapPassEnc);
  if (!pass) return; // password absent or undecryptable — cannot connect, skip quietly

  const client = new ImapFlow({
    host: ib.imapHost,
    port: ib.imapPort || 993,
    secure: ib.imapTls,
    auth: { user: ib.imapUser, pass },
    logger: false,
    emitLogs: false,
  });

  let maxUid = ib.lastImapUid;
  await client.connect();
  try {
    const lock = await client.getMailboxLock("INBOX");
    try {
      const startUid = ib.lastImapUid + 1;
      let seen = 0;
      // UID-based fetch: `${startUid}:*` returns everything above the bookmark. The
      // `X:*` IMAP quirk can echo the latest message even when none is newer, so we
      // re-check `uid > lastImapUid` per row.
      for await (const msg of client.fetch(`${startUid}:*`, { uid: true, source: true, envelope: true }, { uid: true })) {
        if (seen >= MAX_MESSAGES_PER_INBOX) break;
        seen++;
        const uid = msg.uid;
        if (!uid || uid <= ib.lastImapUid) continue;
        if (uid > maxUid) maxUid = uid;
        if (!msg.source) continue;
        try {
          await ingestMessage(ib, uid, await simpleParser(msg.source as Buffer));
        } catch (err) {
          await logEvent("error", "coldemail.inbox.ingest", { inboxId: ib.id, uid, message: String((err as Error)?.message ?? err) });
        }
      }
    } finally {
      lock.release();
    }
  } finally {
    await client.logout().catch(() => null);
  }

  // Advance the bookmark + stamp the poll even when nothing matched, so we never
  // re-scan the same UIDs next sweep.
  await db.inbox
    .update({ where: { id: ib.id }, data: { lastImapUid: Math.max(maxUid, ib.lastImapUid), lastPolledAt: new Date() } })
    .catch(() => null);
}

/** Turn one parsed inbound message into a Conversation + Message (+ side effects). */
async function ingestMessage(ib: PollInbox, uid: number, parsed: ParsedMail): Promise<void> {
  const fromAddr = normalizeEmail(parsed.from?.value?.[0]?.address ?? "");
  if (!fromAddr || !fromAddr.includes("@")) return;
  // Ignore our own sent copies that may live in this mailbox.
  if (fromAddr === normalizeEmail(ib.email)) return;

  // Only capture replies from a KNOWN contact (a reply to our outreach).
  const contact = await db.contact.findUnique({ where: { email: fromAddr }, select: { id: true, fullName: true, stage: true } });
  if (!contact) return;

  const messageId = normalizeMessageId(parsed.messageId) || `<imap-${ib.id}-${uid}@nxeon>`;
  // Idempotency: if we already stored this Message-ID in this inbox's thread, stop.
  const dupe = await db.message.findFirst({
    where: { messageId, conversation: { inboxId: ib.id } },
    select: { id: true },
  });
  if (dupe) return;

  const subject = (parsed.subject ?? "").slice(0, 300);
  const bodyText = (parsed.text ?? "").trim();
  const bodyHtml = typeof parsed.html === "string" ? parsed.html : "";
  const inReplyTo = normalizeMessageId(parsed.inReplyTo);
  const references = Array.isArray(parsed.references)
    ? parsed.references.map(normalizeMessageId).join(" ")
    : normalizeMessageId(parsed.references as string | undefined);
  const receivedAt = parsed.date ?? new Date();

  // ---- Match the originating send (threading first, recipient fallback) ----
  const contactSends = await db.coldSend.findMany({
    where: { contactId: contact.id, inboxId: ib.id },
    orderBy: { createdAt: "desc" },
    select: { id: true, messageId: true, campaignId: true },
  });
  const matchedSendId =
    matchColdSendId(inReplyTo, references, buildSentIndex(contactSends)) ?? (contactSends[0]?.id ?? null);
  const matchedCampaignId =
    contactSends.find((s) => s.id === matchedSendId)?.campaignId ?? contactSends[0]?.campaignId ?? null;

  // ---- Upsert the conversation ----
  const convo = await db.conversation.upsert({
    where: { inboxId_contactId: { inboxId: ib.id, contactId: contact.id } },
    create: {
      inboxId: ib.id,
      contactId: contact.id,
      campaignId: matchedCampaignId,
      subject,
      status: "REPLIED",
      lastMessageAt: receivedAt,
      unread: true,
    },
    update: {
      lastMessageAt: receivedAt,
      unread: true,
      // Fill campaign if we now know it and didn't before.
      ...(matchedCampaignId ? { campaignId: matchedCampaignId } : {}),
    },
    select: { id: true, status: true },
  });

  // ---- Append the inbound message ----
  await db.message.create({
    data: {
      conversationId: convo.id,
      direction: "INBOUND",
      fromAddr,
      toAddr: normalizeEmail(ib.email),
      subject,
      bodyText: bodyText.slice(0, 100_000),
      bodyHtml: bodyHtml.slice(0, 200_000),
      messageId,
      inReplyTo,
      references,
      coldSendId: matchedSendId,
      receivedAt,
    },
  });

  // ---- Advance the contact to REPLIED (never downgrade a warmer stage) ----
  await db.contact.updateMany({
    where: { id: contact.id, stage: { in: ["NEW", "CONTACTED"] } },
    data: { stage: "REPLIED" },
  });

  // ---- HALT the contact's remaining queued sends (mail-side reply detection) ----
  await db.coldSend
    .updateMany({
      where: { contactId: contact.id, status: "QUEUED" },
      data: { status: "CANCELLED", error: "Halted: contact replied" },
    })
    .catch(() => null);

  // ---- Analytics spine: REPLY event(s) ----
  if (matchedSendId) {
    await db.emailEvent.create({ data: { sendId: matchedSendId, type: "REPLY" } }).catch(() => null);
  }
  await db.deliverabilityEvent
    .create({
      data: {
        type: "REPLY",
        inboxId: ib.id,
        campaignId: matchedCampaignId,
        contactId: contact.id,
        sendId: matchedSendId,
        provider: "imap",
      },
    })
    .catch(() => null);

  // ---- Classify (rules always; Claude only if a key exists) ----
  const cls = await classifyReply(subject, bodyText, {});
  const unsub = cls === "UNSUBSCRIBE" || isUnsubscribeRequest(`${subject}\n${bodyText}`);

  const finalStatus = cls ? classToConversationStatus(cls) : convo.status === "OPEN" ? "REPLIED" : "REPLIED";
  await db.conversation.update({
    where: { id: convo.id },
    data: { status: finalStatus, category: cls ?? "" },
  });

  // Stage advancement from the classification (don't clobber WON/MEETING_BOOKED).
  const stageAdvance = cls ? classToContactStage(cls) : null;
  if (stageAdvance) {
    await db.contact
      .updateMany({ where: { id: contact.id, stage: { notIn: ["WON", "MEETING_BOOKED"] } }, data: { stage: stageAdvance } })
      .catch(() => null);
  }

  // ---- Unsubscribe → GLOBAL suppression (idempotent) ----
  if (unsub) {
    const existing = await db.suppression.findFirst({ where: { email: fromAddr, scope: "GLOBAL" }, select: { id: true } });
    if (!existing) {
      await db.suppression.create({ data: { email: fromAddr, scope: "GLOBAL", reason: "UNSUBSCRIBE" } }).catch(() => null);
    }
    await db.emailEvent.create({ data: { sendId: matchedSendId ?? "", type: "UNSUBSCRIBE" } }).catch(() => null);
  }

  // ---- Webhooks ----
  await fireWebhookForReply(convo.id, fromAddr, contact.fullName, matchedCampaignId, ib.email, finalStatus, bodyText, cls, unsub);
}

/** Fan out the reply / interested / unsubscribe webhook events. Best-effort. */
async function fireWebhookForReply(
  conversationId: string,
  contactEmail: string,
  contactName: string | null | undefined,
  campaignId: string | null,
  inboxEmail: string,
  status: string,
  body: string,
  cls: ReplyClass | null,
  unsub: boolean,
): Promise<void> {
  const base = {
    conversationId,
    contactEmail,
    contactName: contactName ?? undefined,
    campaignId,
    inboxEmail,
    status,
    snippet: body.replace(/\s+/g, " ").trim().slice(0, 280),
    occurredAt: new Date().toISOString(),
  };
  await fireWebhooks("reply", base);
  if (cls === "INTERESTED") await fireWebhooks("interested", base);
  if (unsub) await fireWebhooks("unsubscribe", base);
}

