"use server";

// Cold Email Engine — Master Inbox + webhook server actions (Overhaul Phase 1).
//
// Every action re-checks requireArea("platform"). The reply-send path is a normal
// 1:1 email to an EXISTING conversation (someone who already replied to us) sent
// from that inbox's own SMTP — it never touches the bulk queue, so it is allowed
// while the bulk kill-switch is OFF. Webhook signing secrets are stored ENCRYPTED.

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { encryptSecret } from "@/lib/crypto-box";
import { logEvent } from "@/lib/log";
import { sendConversationReply } from "@/lib/coldemail/inbox-send";
import { WEBHOOK_EVENTS, testFireEndpoint, type WebhookEvent } from "@/lib/coldemail/webhooks";

type ActionState = { error?: string; ok?: boolean };

const INBOX_PATH = "/admin/coldemail/inbox";

// ---------------------------------------------------------------------------
// Replies + conversation status
// ---------------------------------------------------------------------------

/** Send a threaded reply from the conversation's inbox and log it. */
export async function sendReply(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const conversationId = String(formData.get("conversationId") ?? "").trim();
  const bodyMarkdown = String(formData.get("body") ?? "");
  const subjectOverride = String(formData.get("subject") ?? "").trim() || undefined;
  if (!conversationId) return { error: "Missing conversation." };

  const res = await sendConversationReply({ conversationId, bodyMarkdown, subjectOverride });
  if (!res.ok) return { error: res.error };
  revalidatePath(INBOX_PATH);
  return { ok: true };
}

/** Mark a conversation read / unread (drives the unibox badge). */
export async function setConversationRead(conversationId: string, unread: boolean): Promise<ActionState> {
  await requireArea("platform");
  await db.conversation.update({ where: { id: conversationId }, data: { unread } }).catch(() => null);
  revalidatePath(INBOX_PATH);
  return { ok: true };
}

/**
 * Operator outcome control (mark interested / not-interested / meeting-booked /
 * closed / reopen). Advances the linked contact's pipeline stage to match so the
 * inbox and the pipeline never disagree.
 */
export type ConversationOutcome =
  | "INTERESTED"
  | "NOT_INTERESTED"
  | "MEETING_BOOKED"
  | "CLOSED"
  | "REOPEN";

export async function setConversationOutcome(conversationId: string, outcome: ConversationOutcome): Promise<ActionState> {
  await requireArea("platform");
  const convo = await db.conversation.findUnique({ where: { id: conversationId }, select: { contactId: true } });
  if (!convo) return { error: "Conversation not found." };

  // (conversation status, category, contact stage) for each outcome.
  const map: Record<
    ConversationOutcome,
    { status: "INTERESTED" | "NOT_INTERESTED" | "CLOSED" | "OPEN"; category: string; stage?: "INTERESTED" | "MEETING_BOOKED" | "LOST" }
  > = {
    INTERESTED: { status: "INTERESTED", category: "INTERESTED", stage: "INTERESTED" },
    NOT_INTERESTED: { status: "NOT_INTERESTED", category: "NOT_INTERESTED", stage: "LOST" },
    MEETING_BOOKED: { status: "INTERESTED", category: "MEETING_BOOKED", stage: "MEETING_BOOKED" },
    CLOSED: { status: "CLOSED", category: "" },
    REOPEN: { status: "OPEN", category: "" },
  };
  const m = map[outcome];

  await db.conversation.update({ where: { id: conversationId }, data: { status: m.status, category: m.category, unread: false } });
  if (m.stage) {
    await db.contact.update({ where: { id: convo.contactId }, data: { stage: m.stage } }).catch(() => null);
  }
  await logEvent("info", "coldemail.conversation.outcome", { conversationId, outcome });
  revalidatePath(INBOX_PATH);
  return { ok: true };
}

/** Manually trigger the IMAP poller (the unibox "Check for replies" button). */
export async function pollInboxesNow(): Promise<ActionState> {
  await requireArea("platform");
  try {
    const { coldEmailInboxPoll } = await import("@/worker/coldemail-inbox");
    await coldEmailInboxPoll();
  } catch (err) {
    await logEvent("error", "coldemail.inbox.manualPoll", { message: String((err as Error)?.message ?? err) });
    return { error: "Could not poll inboxes (are IMAP credentials configured?)." };
  }
  revalidatePath(INBOX_PATH);
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Webhook endpoints
// ---------------------------------------------------------------------------

const WEBHOOKS_PATH = "/admin/coldemail/webhooks";

/** Create or update a webhook endpoint. The signing secret is write-only + encrypted. */
export async function saveWebhookEndpoint(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const id = String(formData.get("id") ?? "").trim() || null;
  const url = String(formData.get("url") ?? "").trim();
  const secretRaw = String(formData.get("secret") ?? "");
  const active = formData.get("active") == null ? true : formData.get("active") === "on" || formData.get("active") === "true";

  if (!/^https:\/\/.+/i.test(url)) return { error: "Enter an https:// endpoint URL." };
  const events = formData
    .getAll("events")
    .map((e) => String(e))
    .filter((e): e is WebhookEvent => (WEBHOOK_EVENTS as string[]).includes(e));
  if (events.length === 0) return { error: "Select at least one event to send." };

  const secretData = secretRaw ? { secretEnc: encryptSecret(secretRaw) } : {};
  try {
    if (id) {
      await db.webhookEndpoint.update({ where: { id }, data: { url, events, active, ...secretData } });
    } else {
      await db.webhookEndpoint.create({ data: { url, events, active, ...secretData } });
    }
  } catch (err) {
    await logEvent("error", "coldemail.webhook.save", { message: String(err) });
    return { error: "Could not save the webhook endpoint." };
  }
  revalidatePath(WEBHOOKS_PATH);
  return { ok: true };
}

export async function deleteWebhookEndpoint(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.webhookEndpoint.delete({ where: { id } }).catch(() => null);
  revalidatePath(WEBHOOKS_PATH);
  return { ok: true };
}

/** Fire a synthetic test event at an endpoint and report the delivery result. */
export async function testWebhookEndpoint(id: string): Promise<ActionState> {
  await requireArea("platform");
  const res = await testFireEndpoint(id);
  revalidatePath(WEBHOOKS_PATH);
  return res.ok ? { ok: true, error: `Test delivered (HTTP ${res.status}).` } : { error: `Test failed: ${res.status}` };
}

"use client";

import { useActionState, useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { StatusDot, Badge } from "@/components/ui/primitives";
import {
  sendReply,
  setConversationOutcome,
  setConversationRead,
  pollInboxesNow,
  type ConversationOutcome,
} from "@/lib/actions-coldemail-inbox";

// Master Inbox (unibox) — a dense, keyboard-friendly two-pane conversation view
// across every inbox. Left: filterable conversation list. Right: the thread +
// a reply composer that sends from the conversation's own inbox, plus outcome
// controls that also move the linked contact's pipeline stage.

export type ConvoSummary = {
  id: string;
  subject: string;
  status: string;
  unread: boolean;
  lastMessageAt: string;
  contactEmail: string;
  contactName: string;
  contactStage: string;
  inboxEmail: string;
  campaignName: string | null;
  snippet: string;
};

export type ThreadMessage = {
  id: string;
  direction: "INBOUND" | "OUTBOUND";
  fromAddr: string;
  toAddr: string;
  subject: string;
  bodyText: string;
  at: string;
};

export type Filter = { key: string; label: string; count: number; active: boolean; query: Record<string, string> };

type Props = {
  convos: ConvoSummary[];
  selectedId: string | null;
  selected: ConvoSummary | null;
  messages: ThreadMessage[];
  statusFilters: Filter[];
  inboxes: { id: string; email: string }[];
  campaigns: { id: string; name: string }[];
  activeInboxId: string;
  activeCampaignId: string;
};

const STATUS_TONE: Record<string, "brand" | "green" | "red" | "amber" | "slate"> = {
  OPEN: "amber",
  REPLIED: "brand",
  INTERESTED: "green",
  NOT_INTERESTED: "red",
  AUTO_REPLY: "slate",
  OUT_OF_OFFICE: "slate",
  UNSUBSCRIBE: "red",
  CLOSED: "slate",
};

function fmtTime(iso: string): string {
  const d = new Date(iso);
  const s = Math.floor((Date.now() - d.getTime()) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)}m`;
  if (s < 86400) return `${Math.floor(s / 3600)}h`;
  if (s < 7 * 86400) return `${Math.floor(s / 86400)}d`;
  return d.toLocaleDateString();
}

export function MasterInbox(props: Props) {
  const { convos, selectedId, selected, messages } = props;
  const router = useRouter();
  const pathname = usePathname();
  const search = useSearchParams();

  // Build a URL that preserves current filters while overriding some params.
  const buildHref = useCallback(
    (overrides: Record<string, string | null>) => {
      const params = new URLSearchParams(search.toString());
      for (const [k, v] of Object.entries(overrides)) {
        if (v === null || v === "") params.delete(k);
        else params.set(k, v);
      }
      const qs = params.toString();
      return qs ? `${pathname}?${qs}` : pathname;
    },
    [pathname, search],
  );

  const selectConvo = useCallback(
    (id: string) => router.push(buildHref({ c: id }), { scroll: false }),
    [router, buildHref],
  );

  // Keyboard: j/k move through the list, u toggles read, r focuses the composer.
  const replyRef = useRef<HTMLTextAreaElement>(null);
  const [, startRead] = useTransition();
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement;
      if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.isContentEditable)) return;
      if (!convos.length) return;
      const idx = convos.findIndex((c) => c.id === selectedId);
      if (e.key === "j") {
        e.preventDefault();
        selectConvo(convos[Math.min(convos.length - 1, idx < 0 ? 0 : idx + 1)].id);
      } else if (e.key === "k") {
        e.preventDefault();
        selectConvo(convos[Math.max(0, idx < 0 ? 0 : idx - 1)].id);
      } else if (e.key === "r" && selectedId) {
        e.preventDefault();
        replyRef.current?.focus();
      } else if (e.key === "u" && selected) {
        e.preventDefault();
        startRead(async () => {
          await setConversationRead(selected.id, !selected.unread);
          router.refresh();
        });
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [convos, selectedId, selected, selectConvo, router]);

  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(300px,380px)_1fr]">
      {/* ---- Left: filters + conversation list ---- */}
      <div className="space-y-3">
        <FilterBar {...props} buildHref={buildHref} />
        <div className="card max-h-[70vh] overflow-y-auto p-0">
          {convos.length === 0 ? (
            <p className="p-6 text-center text-sm text-slate-400">No conversations match these filters.</p>
          ) : (
            <ul className="divide-y divide-white/[0.05]">
              {convos.map((c) => (
                <li key={c.id}>
                  <button
                    onClick={() => selectConvo(c.id)}
                    className={`block w-full px-4 py-3 text-left transition-colors ${
                      c.id === selectedId ? "bg-brand-500/10" : "hover:bg-white/[0.03]"
                    }`}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className={`truncate text-sm ${c.unread ? "font-semibold text-white" : "text-slate-300"}`}>
                        {c.unread && <span className="mr-1.5 inline-block h-2 w-2 rounded-full bg-brand-400 align-middle" />}
                        {c.contactName || c.contactEmail}
                      </span>
                      <span className="shrink-0 text-[11px] text-slate-500">{fmtTime(c.lastMessageAt)}</span>
                    </div>
                    <div className="mt-0.5 truncate text-xs text-slate-400">{c.subject || "(no subject)"}</div>
                    <div className="mt-1 truncate text-xs text-slate-500">{c.snippet}</div>
                    <div className="mt-1.5 flex flex-wrap items-center gap-1.5">
                      <Badge tone={STATUS_TONE[c.status] ?? "slate"}>{c.status.toLowerCase().replace(/_/g, " ")}</Badge>
                      <span className="text-[11px] text-slate-500">{c.inboxEmail}</span>
                      {c.campaignName && <span className="text-[11px] text-slate-600">· {c.campaignName}</span>}
                    </div>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
        <p className="px-1 text-[11px] text-slate-600">
          Shortcuts: <kbd className="rounded bg-white/10 px-1">j</kbd>/<kbd className="rounded bg-white/10 px-1">k</kbd> move ·{" "}
          <kbd className="rounded bg-white/10 px-1">r</kbd> reply · <kbd className="rounded bg-white/10 px-1">u</kbd> unread
        </p>
      </div>

      {/* ---- Right: thread + composer ---- */}
      <div>
        {!selected ? (
          <div className="card flex h-full min-h-[50vh] items-center justify-center text-center">
            <div>
              <p className="text-sm text-slate-400">Select a conversation to read the thread and reply.</p>
              <p className="mt-1 text-xs text-slate-600">Replies send from the inbox that received them.</p>
            </div>
          </div>
        ) : (
          <ThreadPane selected={selected} messages={messages} onRefresh={() => router.refresh()} replyRef={replyRef} />
        )}
      </div>
    </div>
  );
}

function FilterBar(
  props: Props & { buildHref: (o: Record<string, string | null>) => string },
) {
  const { statusFilters, inboxes, campaigns, activeInboxId, activeCampaignId, buildHref } = props;
  const [, startPoll] = useTransition();
  const [polling, setPolling] = useState(false);
  const router = useRouter();

  return (
    <div className="card space-y-3">
      <div className="flex items-center justify-between">
        <p className="section-label">Conversations</p>
        <button
          className="btn-secondary px-2.5 py-1 text-[11px]"
          disabled={polling}
          onClick={() =>
            startPoll(async () => {
              setPolling(true);
              await pollInboxesNow();
              router.refresh();
              setPolling(false);
            })
          }
        >
          {polling ? "Checking…" : "Check for replies"}
        </button>
      </div>
      <div className="flex flex-wrap gap-1.5">
        {statusFilters.map((f) => (
          <Link
            key={f.key}
            href={buildHref({ ...f.query, c: null })}
            className={`rounded-full border px-2.5 py-1 text-xs transition-colors ${
              f.active
                ? "border-brand-500/50 bg-brand-500/15 text-brand-200"
                : "border-white/10 bg-white/[0.03] text-slate-400 hover:text-slate-200"
            }`}
          >
            {f.label}
            {f.count > 0 && <span className="ml-1 text-[10px] opacity-70">{f.count}</span>}
          </Link>
        ))}
      </div>
      <div className="grid grid-cols-2 gap-2">
        <select
          className="input py-1.5 text-xs"
          defaultValue={activeInboxId}
          onChange={(e) => (window.location.href = buildHref({ inbox: e.target.value || null, c: null }))}
        >
          <option value="">All inboxes</option>
          {inboxes.map((i) => (
            <option key={i.id} value={i.id}>
              {i.email}
            </option>
          ))}
        </select>
        <select
          className="input py-1.5 text-xs"
          defaultValue={activeCampaignId}
          onChange={(e) => (window.location.href = buildHref({ campaign: e.target.value || null, c: null }))}
        >
          <option value="">All campaigns</option>
          {campaigns.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
      </div>
    </div>
  );
}

function ThreadPane({
  selected,
  messages,
  onRefresh,
  replyRef,
}: {
  selected: ConvoSummary;
  messages: ThreadMessage[];
  onRefresh: () => void;
  replyRef: React.RefObject<HTMLTextAreaElement | null>;
}) {
  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="card">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <div className="flex items-center gap-2">
              <span className="font-medium text-white">{selected.contactName || selected.contactEmail}</span>
              <Badge tone={STATUS_TONE[selected.status] ?? "slate"}>{selected.status.toLowerCase().replace(/_/g, " ")}</Badge>
              <StatusDot status={selected.contactStage} label={selected.contactStage} />
            </div>
            <p className="mt-1 text-xs text-slate-500">
              {selected.contactEmail} · via <span className="text-slate-400">{selected.inboxEmail}</span>
              {selected.campaignName ? ` · ${selected.campaignName}` : ""}
            </p>
          </div>
          <OutcomeControls conversationId={selected.id} onRefresh={onRefresh} />
        </div>
      </div>

      {/* Thread */}
      <div className="card max-h-[45vh] space-y-3 overflow-y-auto">
        {messages.length === 0 ? (
          <p className="text-sm text-slate-400">No messages captured yet.</p>
        ) : (
          messages.map((m) => (
            <div
              key={m.id}
              className={`rounded-xl border p-3 ${
                m.direction === "INBOUND"
                  ? "border-white/[0.06] bg-white/[0.02]"
                  : "ml-6 border-brand-500/20 bg-brand-500/[0.06]"
              }`}
            >
              <div className="mb-1.5 flex items-center justify-between gap-2 text-[11px] text-slate-500">
                <span>
                  <span className={m.direction === "OUTBOUND" ? "text-brand-300" : "text-slate-300"}>
                    {m.direction === "OUTBOUND" ? "You" : m.fromAddr}
                  </span>{" "}
                  {m.subject ? `· ${m.subject}` : ""}
                </span>
                <span>{new Date(m.at).toLocaleString()}</span>
              </div>
              <pre className="whitespace-pre-wrap break-words font-sans text-sm text-slate-200">{m.bodyText || "(no text body)"}</pre>
            </div>
          ))
        )}
      </div>

      {/* Composer */}
      <ReplyComposer conversationId={selected.id} onSent={onRefresh} replyRef={replyRef} />
    </div>
  );
}

function OutcomeControls({ conversationId, onRefresh }: { conversationId: string; onRefresh: () => void }) {
  const [pending, start] = useTransition();
  const act = (outcome: ConversationOutcome) =>
    start(async () => {
      await setConversationOutcome(conversationId, outcome);
      onRefresh();
    });
  return (
    <div className="flex flex-wrap items-center gap-1.5">
      <button className="btn-secondary px-2.5 py-1 text-xs" disabled={pending} onClick={() => act("INTERESTED")}>
        Interested
      </button>
      <button className="btn-secondary px-2.5 py-1 text-xs" disabled={pending} onClick={() => act("MEETING_BOOKED")}>
        Meeting booked
      </button>
      <button className="btn-secondary px-2.5 py-1 text-xs" disabled={pending} onClick={() => act("NOT_INTERESTED")}>
        Not interested
      </button>
      <button className="btn-ghost px-2.5 py-1 text-xs" disabled={pending} onClick={() => act("CLOSED")}>
        Close
      </button>
    </div>
  );
}

function ReplyComposer({
  conversationId,
  onSent,
  replyRef,
}: {
  conversationId: string;
  onSent: () => void;
  replyRef: React.RefObject<HTMLTextAreaElement | null>;
}) {
  const [state, action, pending] = useActionState(sendReply, {} as { error?: string; ok?: boolean });
  const formRef = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) {
      formRef.current?.reset();
      onSent();
    }
  }, [state, onSent]);
  return (
    <form ref={formRef} action={action} className="card space-y-3">
      <input type="hidden" name="conversationId" value={conversationId} />
      {state?.error && !state.ok && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
      )}
      <textarea
        ref={replyRef}
        name="body"
        rows={5}
        required
        placeholder="Write a reply… it sends from this conversation's inbox and stays in the thread."
        className="input resize-y"
      />
      <div className="flex items-center justify-between">
        <p className="text-[11px] text-slate-600">Threaded reply · plain text + light markdown</p>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Sending…" : "Send reply"}
        </button>
      </div>
    </form>
  );
}

