import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { MasterInbox, type ConvoSummary, type ThreadMessage, type Filter } from "@/components/admin/coldemail/Inbox";
import type { Prisma } from "@prisma/client";

export const dynamic = "force-dynamic";

const STATUS_VALUES = [
  "OPEN",
  "REPLIED",
  "INTERESTED",
  "NOT_INTERESTED",
  "AUTO_REPLY",
  "OUT_OF_OFFICE",
  "UNSUBSCRIBE",
  "CLOSED",
] as const;
type StatusValue = (typeof STATUS_VALUES)[number];

function snippet(text: string): string {
  return text.replace(/\s+/g, " ").trim().slice(0, 120);
}

export default async function ColdEmailInboxPage({
  searchParams,
}: {
  searchParams: Promise<{ c?: string; status?: string; unread?: string; inbox?: string; campaign?: string }>;
}) {
  await requireArea("platform");
  const sp = await searchParams;

  const statusParam = STATUS_VALUES.includes(sp.status as StatusValue) ? (sp.status as StatusValue) : "";
  const unreadOnly = sp.unread === "1";
  const inboxId = sp.inbox ?? "";
  const campaignId = sp.campaign ?? "";

  const where: Prisma.ConversationWhereInput = {};
  if (statusParam) where.status = statusParam;
  if (unreadOnly) where.unread = true;
  if (inboxId) where.inboxId = inboxId;
  if (campaignId) where.campaignId = campaignId;

  let convosRaw: Awaited<ReturnType<typeof loadConvos>> = [];
  let statusCounts: { status: string; _count: { _all: number } }[] = [];
  let unreadCount = 0;
  let totalCount = 0;
  let inboxes: { id: string; email: string }[] = [];
  let campaigns: { id: string; name: string }[] = [];
  let tablesReady = true;

  try {
    [convosRaw, statusCounts, unreadCount, totalCount, inboxes, campaigns] = await Promise.all([
      loadConvos(where),
      db.conversation.groupBy({ by: ["status"], _count: { _all: true } }),
      db.conversation.count({ where: { unread: true } }),
      db.conversation.count(),
      db.inbox.findMany({ orderBy: { email: "asc" }, select: { id: true, email: true } }),
      db.coldCampaign.findMany({ orderBy: { createdAt: "desc" }, select: { id: true, name: true } }),
    ]);
  } catch {
    tablesReady = false;
  }

  const convos: ConvoSummary[] = convosRaw.map((c) => ({
    id: c.id,
    subject: c.subject,
    status: c.status,
    unread: c.unread,
    lastMessageAt: c.lastMessageAt.toISOString(),
    contactEmail: c.contact.email,
    contactName: c.contact.fullName,
    contactStage: c.contact.stage,
    inboxEmail: c.inbox.email,
    campaignName: c.campaign?.name ?? null,
    snippet: snippet(c.messages[0]?.bodyText ?? ""),
  }));

  const selectedId = sp.c && convos.some((c) => c.id === sp.c) ? sp.c : convos[0]?.id ?? null;
  const selected = convos.find((c) => c.id === selectedId) ?? null;

  let messages: ThreadMessage[] = [];
  if (selectedId) {
    const msgs = await db.message
      .findMany({
        where: { conversationId: selectedId },
        orderBy: { createdAt: "asc" },
        select: { id: true, direction: true, fromAddr: true, toAddr: true, subject: true, bodyText: true, sentAt: true, receivedAt: true, createdAt: true },
      })
      .catch(() => []);
    messages = msgs.map((m) => ({
      id: m.id,
      direction: m.direction,
      fromAddr: m.fromAddr,
      toAddr: m.toAddr,
      subject: m.subject,
      bodyText: m.bodyText,
      at: (m.sentAt ?? m.receivedAt ?? m.createdAt).toISOString(),
    }));
  }

  const countFor = (s: string) => statusCounts.find((x) => x.status === s)?._count._all ?? 0;
  const statusFilters: Filter[] = [
    { key: "all", label: "All", count: totalCount, active: !statusParam && !unreadOnly, query: { status: "", unread: "" } },
    { key: "unread", label: "Unread", count: unreadCount, active: unreadOnly, query: { unread: "1", status: "" } },
    { key: "OPEN", label: "Open", count: countFor("OPEN"), active: statusParam === "OPEN", query: { status: "OPEN", unread: "" } },
    { key: "REPLIED", label: "Replied", count: countFor("REPLIED"), active: statusParam === "REPLIED", query: { status: "REPLIED", unread: "" } },
    { key: "INTERESTED", label: "Interested", count: countFor("INTERESTED"), active: statusParam === "INTERESTED", query: { status: "INTERESTED", unread: "" } },
    { key: "NOT_INTERESTED", label: "Not interested", count: countFor("NOT_INTERESTED"), active: statusParam === "NOT_INTERESTED", query: { status: "NOT_INTERESTED", unread: "" } },
    { key: "UNSUBSCRIBE", label: "Unsubscribe", count: countFor("UNSUBSCRIBE"), active: statusParam === "UNSUBSCRIBE", query: { status: "UNSUBSCRIBE", unread: "" } },
  ];

  return (
    <div className="space-y-6">
      <PageHeader
        title="Inbox"
        sub="Unified reply inbox across every mailbox. Replies stop follow-ups, are classified automatically, and send back from the inbox that received them."
      />
      {!tablesReady ? (
        <div className="card text-sm text-slate-400">
          The inbox tables are not migrated on this environment yet. Run a Prisma migration to enable reply capture.
        </div>
      ) : totalCount === 0 ? (
        <div className="card space-y-2">
          <p className="text-sm text-slate-300">No conversations yet.</p>
          <p className="text-sm text-slate-400">
            Configure IMAP credentials on an inbox (Domains &amp; inboxes) and the poller will capture replies here within a
            couple of minutes — or use <span className="text-slate-300">Check for replies</span> once one conversation exists.
            Reply capture works on a single real mailbox without enabling bulk sending.
          </p>
        </div>
      ) : (
        <MasterInbox
          convos={convos}
          selectedId={selectedId}
          selected={selected}
          messages={messages}
          statusFilters={statusFilters}
          inboxes={inboxes}
          campaigns={campaigns}
          activeInboxId={inboxId}
          activeCampaignId={campaignId}
        />
      )}
    </div>
  );
}

function loadConvos(where: Prisma.ConversationWhereInput) {
  return db.conversation.findMany({
    where,
    orderBy: { lastMessageAt: "desc" },
    take: 100,
    include: {
      contact: { select: { email: true, fullName: true, stage: true } },
      inbox: { select: { email: true } },
      campaign: { select: { name: true } },
      messages: { orderBy: { createdAt: "desc" }, take: 1, select: { bodyText: true } },
    },
  });
}

"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  saveWebhookEndpoint,
  deleteWebhookEndpoint,
  testWebhookEndpoint,
} from "@/lib/actions-coldemail-inbox";

type State = { error?: string; ok?: boolean };
const EMPTY: State = {};

const EVENTS: { key: string; label: string; hint: string }[] = [
  { key: "reply", label: "reply", hint: "any inbound reply is captured" },
  { key: "interested", label: "interested", hint: "reply classified as interested" },
  { key: "unsubscribe", label: "unsubscribe", hint: "opt-out request (also suppressed)" },
];

function Banner({ state }: { state: State }) {
  if (state?.error) {
    return (
      <div
        className={`rounded-lg border px-3 py-2 text-sm ${
          state.ok
            ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
            : "border-red-500/30 bg-red-500/10 text-red-400"
        }`}
      >
        {state.error}
      </div>
    );
  }
  if (state?.ok) {
    return <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">Endpoint saved.</div>;
  }
  return null;
}

export function WebhookForm() {
  const [state, action, pending] = useActionState(saveWebhookEndpoint, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="space-y-4">
      <Banner state={state} />
      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label">Endpoint URL (https)</label>
          <input className="input" name="url" placeholder="https://hooks.your-crm.com/nxeon" required />
        </div>
        <div>
          <label className="label">Signing secret (write-only)</label>
          <input className="input" name="secret" type="password" placeholder="used for HMAC signature" autoComplete="new-password" />
        </div>
      </div>
      <div>
        <label className="label mb-1 block">Events</label>
        <div className="flex flex-wrap gap-4">
          {EVENTS.map((e) => (
            <label key={e.key} className="flex items-center gap-2 text-sm text-slate-300">
              <input type="checkbox" name="events" value={e.key} defaultChecked={e.key === "reply"} />
              <span>
                {e.label}
                <span className="block text-[11px] text-slate-500">{e.hint}</span>
              </span>
            </label>
          ))}
        </div>
      </div>
      <label className="flex items-center gap-2 text-sm text-slate-300">
        <input type="checkbox" name="active" defaultChecked /> Active
      </label>
      <p className="text-xs text-slate-500">
        Each delivery is a POST with header <code className="text-slate-400">X-Nxeon-Signature: sha256=&lt;hmac&gt;</code> over the raw JSON
        body — recompute it with your secret to verify authenticity.
      </p>
      <div className="flex justify-end">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Add endpoint"}
        </button>
      </div>
    </form>
  );
}

export function WebhookControls({ id }: { id: string }) {
  const [pending, start] = useTransition();
  const [confirming, setConfirming] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <div className="flex flex-wrap items-center justify-end gap-2">
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
      <button
        className="btn-secondary px-3 py-1.5 text-xs"
        disabled={pending}
        onClick={() =>
          start(async () => {
            const r = await testWebhookEndpoint(id);
            setMsg(r.error ?? (r.ok ? "sent" : "failed"));
          })
        }
      >
        {pending ? "…" : "Test-fire"}
      </button>
      {confirming ? (
        <>
          <button className="btn-danger px-3 py-1.5 text-xs" disabled={pending} onClick={() => start(async () => void (await deleteWebhookEndpoint(id)))}>
            Confirm
          </button>
          <button className="btn-ghost px-2 py-1.5 text-xs" onClick={() => setConfirming(false)}>
            Cancel
          </button>
        </>
      ) : (
        <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
          Delete
        </button>
      )}
    </div>
  );
}

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
import { WebhookForm, WebhookControls } from "@/components/admin/coldemail/Webhooks";

export const dynamic = "force-dynamic";

export default async function ColdEmailWebhooksPage() {
  await requireArea("platform");

  let endpoints: {
    id: string;
    url: string;
    events: string[];
    active: boolean;
    lastFiredAt: Date | null;
    lastStatus: string;
  }[] = [];
  let ready = true;
  try {
    endpoints = await db.webhookEndpoint.findMany({
