        sub="Fire HMAC-signed POSTs to Nxeon or an external CRM on reply / interested / unsubscribe events."
      />

      <div className="card">
        <p className="section-label mb-4">Add an endpoint</p>
        <WebhookForm />
      </div>

      {!ready ? (
        <div className="card text-sm text-slate-400">
          The webhook table is not migrated on this environment yet. Run a Prisma migration to enable webhooks.
        </div>
      ) : endpoints.length === 0 ? (
        <EmptyState
          title="No webhook endpoints"
          sub="Add an https endpoint above to receive reply, interested, and unsubscribe events as they happen."
        />
      ) : (
        <div className="card overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
                <th className="py-2 pr-3">Endpoint</th>
                <th className="py-2 pr-3">Events</th>
                <th className="py-2 pr-3">Status</th>
                <th className="py-2 pr-3">Last delivery</th>
                <th className="py-2 pr-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {endpoints.map((e) => (
                <tr key={e.id} className="border-t border-white/[0.05]">
                  <td className="py-2 pr-3 font-mono text-xs text-slate-200">{e.url}</td>
                  <td className="py-2 pr-3">
                    <div className="flex flex-wrap gap-1">
                      {e.events.map((ev) => (
                        <Badge key={ev} tone="slate">
                          {ev}
                        </Badge>
                      ))}
                    </div>
                  </td>
                  <td className="py-2 pr-3">
                    {e.active ? <Badge tone="green">active</Badge> : <Badge tone="slate">paused</Badge>}
                  </td>
                  <td className="py-2 pr-3 text-xs text-slate-500">
                    {e.lastFiredAt ? `${new Date(e.lastFiredAt).toLocaleString()} · ${e.lastStatus || "—"}` : "never"}
                  </td>
                  <td className="py-2 pr-3">
                    <WebhookControls id={e.id} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { test } from "node:test";
import assert from "node:assert/strict";

// crypto-box (pulled in transitively by classify → anthropic) derives from AUTH_SECRET.
process.env.AUTH_SECRET = process.env.AUTH_SECRET || "test-secret-for-coldemail";
process.env.APP_URL = process.env.APP_URL || "https://nxeon.cloud";

import {
  extractMessageIds,
  normalizeMessageId,
  replySubject,
  buildThreadHeaders,
} from "../lib/coldemail/threading.ts";
import { matchColdSendId, buildSentIndex } from "../lib/coldemail/inbox-match.ts";
import {
  ruleClassify,
  isUnsubscribeRequest,
  classNeedsSuppression,
  classToConversationStatus,
  classToContactStage,
  parseAiClass,
  type ReplyClass,
} from "../lib/coldemail/classify.ts";

// ---------------------------------------------------------------------------
// Threading header build
// ---------------------------------------------------------------------------

test("extractMessageIds parses one or many angle-bracket ids", () => {
  assert.deepEqual(extractMessageIds("<a@x>"), ["<a@x>"]);
  assert.deepEqual(extractMessageIds("<a@x> <b@y>\t<c@z>"), ["<a@x>", "<b@y>", "<c@z>"]);
  assert.deepEqual(extractMessageIds(""), []);
  assert.deepEqual(extractMessageIds(null), []);
  // A bare id with no brackets is tolerated.
  assert.deepEqual(extractMessageIds("bare@id"), ["<bare@id>"]);
});

test("normalizeMessageId adds brackets idempotently", () => {
  assert.equal(normalizeMessageId("a@b"), "<a@b>");
  assert.equal(normalizeMessageId("<a@b>"), "<a@b>");
  assert.equal(normalizeMessageId(""), "");
  assert.equal(normalizeMessageId(undefined), "");
});

test("replySubject prefixes Re: exactly once", () => {
  assert.equal(replySubject("Quick question"), "Re: Quick question");
  assert.equal(replySubject("Re: Quick question"), "Re: Quick question");
  assert.equal(replySubject("RE: shouty"), "RE: shouty");
  assert.equal(replySubject(""), "Re:");
});

test("buildThreadHeaders sets In-Reply-To and appends parent to the References chain", () => {
  const h = buildThreadHeaders("<msg-3@inbox>", "<msg-1@send> <msg-2@reply>");
  assert.equal(h["In-Reply-To"], "<msg-3@inbox>");
  assert.equal(h.References, "<msg-1@send> <msg-2@reply> <msg-3@inbox>");
});

test("buildThreadHeaders de-dupes an id already in the chain and handles no parent", () => {
  const h = buildThreadHeaders("<msg-1@send>", "<msg-1@send>");
  assert.equal(h.References, "<msg-1@send>");
  assert.deepEqual(buildThreadHeaders("", ""), {});
});

// ---------------------------------------------------------------------------
// Reply → originating-send matching
// ---------------------------------------------------------------------------

test("buildSentIndex maps normalized message ids to send ids, skipping null", () => {
  const idx = buildSentIndex([
    { id: "send-A", messageId: "<out-1@mail>" },
    { id: "send-B", messageId: "out-2@mail" }, // gets normalized
    { id: "send-C", messageId: null },
  ]);
  assert.equal(idx.get("<out-1@mail>"), "send-A");
  assert.equal(idx.get("<out-2@mail>"), "send-B");
  assert.equal(idx.has("<none>"), false);
  assert.equal(idx.size, 2);
});

test("matchColdSendId: In-Reply-To wins over References", () => {
  const idx = buildSentIndex([
    { id: "send-A", messageId: "<out-1@mail>" },
    { id: "send-B", messageId: "<out-2@mail>" },
  ]);
  // In-Reply-To points at send-B; References also contains out-1 — In-Reply-To must win.
  const hit = matchColdSendId("<out-2@mail>", "<out-1@mail> <foreign@x>", idx);
  assert.equal(hit, "send-B");
});

test("matchColdSendId: falls back to the most-recent References match", () => {
  const idx = buildSentIndex([
    { id: "send-A", messageId: "<out-1@mail>" },
    { id: "send-B", messageId: "<out-2@mail>" },
  ]);
  // No In-Reply-To; References newest-last → out-2 (send-B) is the best match.
  const hit = matchColdSendId("", "<out-1@mail> <out-2@mail>", idx);
  assert.equal(hit, "send-B");
});

test("matchColdSendId returns null when nothing threads back to a known send", () => {
  const idx = buildSentIndex([{ id: "send-A", messageId: "<out-1@mail>" }]);
  assert.equal(matchColdSendId("<unknown@x>", "<also-unknown@y>", idx), null);
  assert.equal(matchColdSendId("", "", idx), null);
});

// ---------------------------------------------------------------------------
// Unsubscribe detection → suppression decision
// ---------------------------------------------------------------------------

test("isUnsubscribeRequest catches opt-out phrasing, ignores ordinary replies", () => {
  assert.equal(isUnsubscribeRequest("Please unsubscribe me from this list"), true);
  assert.equal(isUnsubscribeRequest("take me off your list"), true);
  assert.equal(isUnsubscribeRequest("Stop emailing me"), true);
  assert.equal(isUnsubscribeRequest("do not contact me again"), true);
  assert.equal(isUnsubscribeRequest("Thanks, this looks interesting — tell me more"), false);
});

test("ruleClassify flags an unsubscribe and classNeedsSuppression only fires for it", () => {
  assert.equal(ruleClassify("please remove me from your emails"), "UNSUBSCRIBE");
  assert.equal(classNeedsSuppression("UNSUBSCRIBE"), true);
  for (const c of ["INTERESTED", "NOT_INTERESTED", "AUTO_REPLY", "OUT_OF_OFFICE"] as ReplyClass[]) {
    assert.equal(classNeedsSuppression(c), false);
  }
});

// ---------------------------------------------------------------------------
// Classification result → conversation status / contact stage mapping
// ---------------------------------------------------------------------------

test("ruleClassify buckets common replies (precedence: unsub > auto > ooo > sentiment)", () => {
  assert.equal(ruleClassify("I'm currently out of office until Monday"), "OUT_OF_OFFICE");
  assert.equal(ruleClassify("This is an automated reply, do not reply"), "AUTO_REPLY");
  assert.equal(ruleClassify("Not interested, thanks"), "NOT_INTERESTED");
  assert.equal(ruleClassify("Sounds great, let's book a call"), "INTERESTED");
  assert.equal(ruleClassify("hey"), null); // ambiguous → hand off to AI (or leave OPEN)
});

test("classToConversationStatus maps every bucket", () => {
  assert.equal(classToConversationStatus("INTERESTED"), "INTERESTED");
  assert.equal(classToConversationStatus("NOT_INTERESTED"), "NOT_INTERESTED");
  assert.equal(classToConversationStatus("AUTO_REPLY"), "AUTO_REPLY");
  assert.equal(classToConversationStatus("OUT_OF_OFFICE"), "OUT_OF_OFFICE");
  assert.equal(classToConversationStatus("UNSUBSCRIBE"), "UNSUBSCRIBE");
});

test("classToContactStage advances only on a human signal", () => {
  assert.equal(classToContactStage("INTERESTED"), "INTERESTED");
  assert.equal(classToContactStage("NOT_INTERESTED"), "LOST");
  assert.equal(classToContactStage("UNSUBSCRIBE"), "LOST");
  assert.equal(classToContactStage("AUTO_REPLY"), null);
  assert.equal(classToContactStage("OUT_OF_OFFICE"), null);
});

test("parseAiClass reads a bucket out of a free-form answer", () => {
  assert.equal(parseAiClass("INTERESTED"), "INTERESTED");
  assert.equal(parseAiClass("The reply is not interested in this"), "NOT_INTERESTED");
  assert.equal(parseAiClass("out of office"), "OUT_OF_OFFICE");
  assert.equal(parseAiClass("banana"), null);
});
